// Generated by scripts/generate-articles.ts. Do not edit.
export default {"html":"<p data-line=\"0\" class=\"code-line\">Angular has a new forms API called Signal Forms, imported from <code>@angular/forms/signals</code>. It is still experimental, but I combined it with Ionic Framework and it worked fine—here are the migration patterns I used.</p>\n<p data-line=\"2\" class=\"code-line\"><a href=\"https://angular.dev/essentials/signal-forms\" rel=\"noopener noreferrer\" target=\"_blank\">https://angular.dev/essentials/signal-forms</a><a href=\"https://angular.dev/essentials/signal-forms\" style=\"display:none\" target=\"_blank\" rel=\"noopener noreferrer\">https://angular.dev/essentials/signal-forms</a></p>\n<h2 id=\"what-are-signal-forms%3F\" data-line=\"4\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#what-are-signal-forms%3F\" aria-hidden=\"true\"></a> What are Signal Forms?</h2>\n<p data-line=\"6\" class=\"code-line\">Signal Forms is Angular's new form management API. Unlike template-driven forms (<code>FormsModule</code> + <code>ngModel</code>) or reactive forms (<code>ReactiveFormsModule</code>), it takes a Signal-based approach.</p>\n<p data-line=\"8\" class=\"code-line\">With traditional <code>ngModel</code> forms, two-way binding managed values. With Signal Forms, I define the model with <code>signal()</code> and build the form tree with <code>form()</code>. Validation can be schema-based, so separation of template and logic is clearer.</p>\n<h2 id=\"basic-migration-pattern\" data-line=\"10\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#basic-migration-pattern\" aria-hidden=\"true\"></a> Basic migration pattern</h2>\n<p data-line=\"12\" class=\"code-line\">Migration was simple in practice. First, template-driven form style:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"14\"><span class=\"line\"><span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> { FormsModule } </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> '@angular/forms'</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  imports: [FormsModule, IonInput],</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> SigninPage</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  email</span><span style=\"color:#F97583\"> =</span><span style=\"color:#9ECBFF\"> ''</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  password</span><span style=\"color:#F97583\"> =</span><span style=\"color:#9ECBFF\"> ''</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"26\"><span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">form</span><span style=\"color:#B392F0\"> (submit)</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"submit()\"</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-input</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    [(ngModel)]</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"email\"</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    name</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"email\"</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    [required]</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"true\"</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &gt;&lt;/</span><span style=\"color:#85E89D\">ion-input</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-input</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    [(ngModel)]</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"password\"</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    name</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"password\"</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    [required]</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"true\"</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &gt;&lt;/</span><span style=\"color:#85E89D\">ion-input</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;/</span><span style=\"color:#85E89D\">form</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"41\" class=\"code-line\">Migrated to Signal Forms:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"43\"><span class=\"line\"><span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> { form, FormField, required } </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> '@angular/forms/signals'</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">interface</span><span style=\"color:#B392F0\"> ILogin</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  email</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> string</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  password</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> string</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  imports: [FormField, IonInput],</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> SigninPage</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  readonly</span><span style=\"color:#FFAB70\"> loginModel</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> signal</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">ILogin</span><span style=\"color:#E1E4E8\">&gt;({ email: </span><span style=\"color:#9ECBFF\">''</span><span style=\"color:#E1E4E8\">, password: </span><span style=\"color:#9ECBFF\">''</span><span style=\"color:#E1E4E8\"> });</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  readonly</span><span style=\"color:#FFAB70\"> loginForm</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> form</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.loginModel, (</span><span style=\"color:#FFAB70\">schemaPath</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    required</span><span style=\"color:#E1E4E8\">(schemaPath.email);</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    required</span><span style=\"color:#E1E4E8\">(schemaPath.password);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  });</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"63\"><span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">form</span><span style=\"color:#B392F0\"> novalidate</span><span style=\"color:#B392F0\"> (submit)</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"submit($event)\"</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-input</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    [formField]</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"loginForm.email\"</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &gt;&lt;/</span><span style=\"color:#85E89D\">ion-input</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-input</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    [formField]</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"loginForm.password\"</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &gt;&lt;/</span><span style=\"color:#85E89D\">ion-input</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;/</span><span style=\"color:#85E89D\">form</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"74\" class=\"code-line\">Summary of changes: define the model with <code>signal()</code> and the form with <code>form()</code>. In the template, replace <code>[(ngModel)]</code> with <code>[formField]</code>; <code>name</code> is unnecessary. Remove <code>[required]=\"true\"</code> from the template and define <code>required()</code> in the schema.</p>\n<p data-line=\"76\" class=\"code-line\">Important: do not use <code>undefined</code> in initial model values. Signal Forms does not support <code>undefined</code>; the <code>FormField</code> directive throws <code>TypeError: this.formField(...) is not a function</code>. Use <code>null</code> for empty values.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"78\"><span class=\"line\"><span style=\"color:#a0aab5\">// NG: undefined cannot be used</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">readonly optionsModel </span><span style=\"color:#F97583\">=</span><span style=\"color:#B392F0\"> signal</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">IOptions</span><span style=\"color:#E1E4E8\">&gt;({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  measureType: </span><span style=\"color:#79B8FF\">undefined</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  measureSize: </span><span style=\"color:#79B8FF\">undefined</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">// OK: use null</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">readonly optionsModel </span><span style=\"color:#F97583\">=</span><span style=\"color:#B392F0\"> signal</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">IOptions</span><span style=\"color:#E1E4E8\">&gt;({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  measureType: </span><span style=\"color:#79B8FF\">null</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  measureSize: </span><span style=\"color:#79B8FF\">null</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"accessing-and-updating-values\" data-line=\"92\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#accessing-and-updating-values\" aria-hidden=\"true\"></a> Accessing and updating values</h2>\n<p data-line=\"94\" class=\"code-line\">Access patterns change too. With Signal Forms I can read from the model directly or from form fields.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"96\"><span class=\"line\"><span style=\"color:#a0aab5\">// Read directly from the model</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#E1E4E8\"> { </span><span style=\"color:#79B8FF\">email</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#79B8FF\">password</span><span style=\"color:#E1E4E8\"> } </span><span style=\"color:#F97583\">=</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">loginModel</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">// Read from the form field</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> email</span><span style=\"color:#F97583\"> =</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.loginForm.</span><span style=\"color:#B392F0\">email</span><span style=\"color:#E1E4E8\">().</span><span style=\"color:#B392F0\">value</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"104\" class=\"code-line\">Updates work similarly—from the model or from individual fields.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"106\"><span class=\"line\"><span style=\"color:#a0aab5\">// Update the entire model</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.loginModel.</span><span style=\"color:#B392F0\">update</span><span style=\"color:#E1E4E8\">((</span><span style=\"color:#FFAB70\">m</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> ({ </span><span style=\"color:#F97583\">...</span><span style=\"color:#E1E4E8\">m, email: </span><span style=\"color:#9ECBFF\">'new@example.com'</span><span style=\"color:#E1E4E8\"> }));</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">// Update an individual field</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.loginForm.</span><span style=\"color:#B392F0\">email</span><span style=\"color:#E1E4E8\">().value.</span><span style=\"color:#B392F0\">set</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'new@example.com'</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"114\" class=\"code-line\"><code>undefined</code> is not allowed on update either—not only initial values. If local storage or API data contains <code>undefined</code>, convert to <code>null</code> before setting the model.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"116\"><span class=\"line\"><span style=\"color:#E1E4E8\">async </span><span style=\"color:#B392F0\">load</span><span style=\"color:#E1E4E8\">() {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  const</span><span style=\"color:#79B8FF\"> options</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> await</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.storage.</span><span style=\"color:#B392F0\">get</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'printOptions'</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  if</span><span style=\"color:#E1E4E8\"> (options) {</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">    // Convert undefined to null before setting it on the model</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    if</span><span style=\"color:#E1E4E8\"> (options.measureType </span><span style=\"color:#F97583\">===</span><span style=\"color:#79B8FF\"> undefined</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      options.measureType </span><span style=\"color:#F97583\">=</span><span style=\"color:#79B8FF\"> null</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    }</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    if</span><span style=\"color:#E1E4E8\"> (options.measureSize </span><span style=\"color:#F97583\">===</span><span style=\"color:#79B8FF\"> undefined</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      options.measureSize </span><span style=\"color:#F97583\">=</span><span style=\"color:#79B8FF\"> null</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    }</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.optionsModel.</span><span style=\"color:#B392F0\">set</span><span style=\"color:#E1E4E8\">(options);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"132\" class=\"code-line\">When migrating existing apps, check local storage and API responses for <code>undefined</code> and add migration handling as needed.</p>\n<h2 id=\"form-submit-handler-changes\" data-line=\"134\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#form-submit-handler-changes\" aria-hidden=\"true\"></a> Form submit handler changes</h2>\n<p data-line=\"136\" class=\"code-line\">On submit, call <code>event.preventDefault()</code>.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"138\"><span class=\"line\"><span style=\"color:#B392F0\">submit</span><span style=\"color:#E1E4E8\">(event: Event) {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  event.</span><span style=\"color:#B392F0\">preventDefault</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  const</span><span style=\"color:#E1E4E8\"> { </span><span style=\"color:#79B8FF\">email</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#79B8FF\">password</span><span style=\"color:#E1E4E8\"> } </span><span style=\"color:#F97583\">=</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">loginModel</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">  // Submit</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"146\" class=\"code-line\">In the template, add <code>novalidate</code> to <code>&lt;form&gt;</code> and pass <code>$event</code> to the handler.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"148\"><span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">form</span><span style=\"color:#B392F0\"> novalidate</span><span style=\"color:#B392F0\"> (submit)</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"submit($event)\"</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"152\" class=\"code-line\"><code>novalidate</code> disables browser-native validation. HTML5 validates elements with <code>required</code>, <code>min</code>, <code>max</code>, etc. If that stays enabled while Signal Forms controls validation, the browser may show its own errors or block submit unexpectedly.</p>\n<p data-line=\"154\" class=\"code-line\">Because Signal Forms defines validation in a schema, running browser validation in parallel can cause surprises. <code>novalidate</code> centralizes control on Signal Forms.</p>\n<h2 id=\"validation\" data-line=\"156\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#validation\" aria-hidden=\"true\"></a> Validation</h2>\n<p data-line=\"158\" class=\"code-line\">Signal Forms defines validation in a schema. Helpers include <code>required()</code>, <code>minLength()</code>, <code>min()</code>, <code>max()</code>, and <code>readonly()</code>.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"160\"><span class=\"line\"><span style=\"color:#E1E4E8\">readonly optionsForm </span><span style=\"color:#F97583\">=</span><span style=\"color:#B392F0\"> form</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.optionsModel, (</span><span style=\"color:#FFAB70\">schemaPath</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  min</span><span style=\"color:#E1E4E8\">(schemaPath.printNum, </span><span style=\"color:#79B8FF\">1</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  max</span><span style=\"color:#E1E4E8\">(schemaPath.printNum, </span><span style=\"color:#79B8FF\">40</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  min</span><span style=\"color:#E1E4E8\">(schemaPath.fontSize, </span><span style=\"color:#79B8FF\">8</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  max</span><span style=\"color:#E1E4E8\">(schemaPath.fontSize, </span><span style=\"color:#79B8FF\">14</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"169\" class=\"code-line\">Read-only fields belong in the schema, not as <code>[readonly]=\"true\"</code> in the template.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"171\"><span class=\"line\"><span style=\"color:#E1E4E8\">readonly generatedForm </span><span style=\"color:#F97583\">=</span><span style=\"color:#B392F0\"> form</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.generatedModel, (</span><span style=\"color:#FFAB70\">schemaPath</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  readonly</span><span style=\"color:#E1E4E8\">(schemaPath.productName);</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  readonly</span><span style=\"color:#E1E4E8\">(schemaPath.categoryName);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"notes-with-ionic\" data-line=\"178\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#notes-with-ionic\" aria-hidden=\"true\"></a> Notes with Ionic</h2>\n<p data-line=\"180\" class=\"code-line\">One caveat combining with Ionic Framework. On standard HTML <code>&lt;input&gt;</code>, <code>[required]</code> and <code>[min]</code> conflict with <code>formField</code> and error:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"182\"><span class=\"line\"><span>NG8022: Setting the 'required' attribute is not allowed on nodes using the '[formField]' directive</span></span>\n<span class=\"line\"><span></span></span></code></pre></div><p data-line=\"186\" class=\"code-line\">On Ionic <code>&lt;ion-input&gt;</code>, this error does not appear. <code>ion-input</code> is a Web Component with different attribute handling. With Ionic, leaving <code>[required]</code> in the template may still work, but defining rules in the schema is more consistent.</p>\n<p data-line=\"188\" class=\"code-line\">Signal Forms reflects schema <code>required()</code> and <code>readonly()</code> onto DOM elements with <code>[formField]</code> as <code>required</code> and <code>readonly</code> attributes. Ionic components watch these; <code>&lt;ion-input&gt;</code> and <code>&lt;ion-textarea&gt;</code> propagate them to internal native <code>&lt;input&gt;</code> and <code>&lt;textarea&gt;</code>. Defining <code>required()</code> in the schema means Ionic handles it without <code>[required]=\"true\"</code> in the template.</p>\n<h2 id=\"css-updates\" data-line=\"190\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#css-updates\" aria-hidden=\"true\"></a> CSS updates</h2>\n<p data-line=\"192\" class=\"code-line\">Removing <code>[required]</code> from the template may require updating CSS selectors—for example, badges on required fields.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"194\"><span class=\"line\"><span style=\"color:#a0aab5\">// Before</span></span>\n<span class=\"line\"><span style=\"color:#85E89D\">*</span><span style=\"color:#E1E4E8\">[</span><span style=\"color:#B392F0\">required</span><span style=\"color:#E1E4E8\">] </span><span style=\"color:#85E89D\">label</span><span style=\"color:#B392F0\"> .label-text::before</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#85E89D\">  content</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#9ECBFF\">'Required'</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">// After - use the :has() pseudo-class</span></span>\n<span class=\"line\"><span style=\"color:#85E89D\">*</span><span style=\"color:#B392F0\">:has</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#B392F0\">.native-wrapper</span><span style=\"color:#F97583\"> &gt;</span><span style=\"color:#85E89D\"> *</span><span style=\"color:#E1E4E8\">[</span><span style=\"color:#B392F0\">required</span><span style=\"color:#E1E4E8\">]) </span><span style=\"color:#85E89D\">label</span><span style=\"color:#B392F0\"> .label-text::before</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#85E89D\">  content</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#9ECBFF\">'Required'</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"206\" class=\"code-line\">The <code>:has()</code> pseudo-class applies styles when a child has a <code>required</code> attribute.</p>\n<h2 id=\"summary\" data-line=\"208\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#summary\" aria-hidden=\"true\"></a> Summary</h2>\n<p data-line=\"210\" class=\"code-line\">Signal Forms is Angular's new form management API. Still experimental, but it worked fine with Ionic Framework. Migration is simple: <code>signal()</code> + <code>form()</code>, swap <code>[(ngModel)]</code> for <code>[formField]</code>.</p>\n<p data-line=\"212\" class=\"code-line\">Schema-based validation clarifies template vs logic separation. The <code>undefined</code> constraint means watch data migration when moving existing apps. When the API stabilizes, full adoption may be worth considering.</p>\n<p data-line=\"214\" class=\"code-line\">See you next time.</p>\n","headings":[{"id":"what-are-signal-forms%3F","text":"What are Signal Forms?","level":2},{"id":"basic-migration-pattern","text":"Basic migration pattern","level":2},{"id":"accessing-and-updating-values","text":"Accessing and updating values","level":2},{"id":"form-submit-handler-changes","text":"Form submit handler changes","level":2},{"id":"validation","text":"Validation","level":2},{"id":"notes-with-ionic","text":"Notes with Ionic","level":2},{"id":"css-updates","text":"CSS updates","level":2},{"id":"summary","text":"Summary","level":2}]} as const;
